package com.travbook.holidays.domain.model;
import com.travbook.shared.domain.*;
import java.time.*;
import java.math.*;
import java.util.*;
public final class Holiday{
 private Holiday(){}public enum Region{DOMESTIC,INTERNATIONAL}public enum Theme{BEACH,CULTURE,NATURE}public enum Fulfilment{DIRECT,ENQUIRY}public enum Upgrade{STANDARD,COMFORT}public enum RegionFilter{ALL,DOMESTIC,INTERNATIONAL}public enum ThemeFilter{ALL,BEACH,CULTURE,NATURE}public enum Sort{PRICE,DURATION}
 public record Day(int day,String title,String description,String hotel,List<String> meals,String transport){public Day{meals=List.copyOf(meals);}}
 public record Package(String id,String supplier,String title,String destination,Region region,Theme theme,int nights,int days,String image,String summary,List<String> highlights,List<Day> itinerary,List<String> inclusions,List<String> exclusions,List<LocalDate> departures,TravelMoney adultFrom,boolean customizable,Fulfilment fulfilment,String cancellationPolicy,String paymentPolicy,String eligibility,String timezone){public Package{highlights=List.copyOf(highlights);itinerary=List.copyOf(itinerary);inclusions=List.copyOf(inclusions);exclusions=List.copyOf(exclusions);departures=List.copyOf(departures);if(days!=nights+1||itinerary.size()!=days)throw new IllegalArgumentException("Incomplete itinerary");}}
 public record Inventory(List<Package> packages,List<SupplierCoverage> coverage){}
 public record Filter(String destination,RegionFilter region,ThemeFilter theme,BigDecimal maxPrice,int maxDays,Sort sort){public Filter{if(destination==null||destination.length()>80||region==null||theme==null||sort==null||maxDays<2||maxDays>30||maxPrice==null||maxPrice.signum()<0||maxPrice.scale()>2||maxPrice.compareTo(new BigDecimal("99999999"))>0)throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Invalid holiday filters.");}}
 public record Page(List<Package> items,List<SupplierCoverage> coverage,String mode,Instant observedAt,int total){}
 public record Selection(String packageId,LocalDate departure,int adults,List<Integer> childAges,Upgrade upgrade,boolean extraActivity){public Selection{childAges=List.copyOf(childAges);if(packageId==null||!packageId.matches("[a-z0-9-]{1,80}")||departure==null||adults<1||adults>6||childAges.size()>4||childAges.stream().anyMatch(a->a<0||a>11)||upgrade==null)throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Choose valid package, party ages and customization.");}}
 public record Quote(UUID id,UUID owner,int version,Package travelPackage,Selection selection,TravelMoney subtotal,TravelMoney taxes,TravelMoney fees,TravelMoney total,Instant createdAt,Instant expiresAt,String mode){public Quote{if(version!=1||!"MOCK".equals(mode)||!expiresAt.isAfter(createdAt)||!selection.packageId().equals(travelPackage.id())||subtotal.decimal().add(taxes.decimal()).add(fees.decimal()).compareTo(total.decimal())!=0)throw new IllegalArgumentException("Invalid immutable holiday quote");}public boolean expired(Instant now){return !expiresAt.isAfter(now);}public void valid(Instant now){if(expired(now))throw new DomainFailure(DomainFailure.Code.QUOTE_EXPIRED,"Holiday quote expired; request current terms.");}}
 public static Quote quote(UUID owner,Package p,Selection s,Instant now){if(!p.departures().contains(s.departure()))throw new DomainFailure(DomainFailure.Code.OFFER_UNAVAILABLE,"This package departure is not available.");if(!p.customizable()&&(s.upgrade()!=Upgrade.STANDARD||s.extraActivity()))throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"This package does not support customization.");BigDecimal units=BigDecimal.valueOf(s.adults());for(int age:s.childAges())units=units.add(new BigDecimal(age<5?"0.25":"0.60"));BigDecimal base=p.adultFrom().decimal().multiply(units);if(s.upgrade()==Upgrade.COMFORT)base=base.add(BigDecimal.valueOf((long)(s.adults()+s.childAges().size())*p.nights()*750));if(s.extraActivity())base=base.add(BigDecimal.valueOf((long)(s.adults()+s.childAges().size())*1200));BigDecimal tax=base.multiply(new BigDecimal("0.10")).setScale(2,RoundingMode.HALF_UP);var fees=TravelMoney.inr(200);var days=p.itinerary().stream().map(d->new Day(d.day(),d.title(),d.description()+(s.extraActivity()&&d.day()==2?" Includes the sample extra activity.":""),s.upgrade()==Upgrade.COMFORT?d.hotel().replace("standard room","comfort room"):d.hotel(),d.meals(),d.transport())).toList();var inclusions=new ArrayList<>(p.inclusions().stream().map(v->s.upgrade()==Upgrade.COMFORT?v.replace("standard hotel","comfort hotel"):v).toList());if(s.extraActivity())inclusions.add("Sample extra activity on day 2");var quoted=new Package(p.id(),p.supplier(),p.title(),p.destination(),p.region(),p.theme(),p.nights(),p.days(),p.image(),p.summary(),p.highlights(),days,inclusions,p.exclusions(),p.departures(),p.adultFrom(),p.customizable(),p.fulfilment(),p.cancellationPolicy(),p.paymentPolicy(),p.eligibility(),p.timezone());return new Quote(UUID.randomUUID(),owner,1,quoted,s,TravelMoney.inr(base),TravelMoney.inr(tax),fees,TravelMoney.inr(base.add(tax).add(fees.decimal())),now,now.plusSeconds(600),"MOCK");}
 public record Contact(String contactName,String email,String notes){public Contact{if(contactName==null||email==null||notes==null)throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Contact details required.");contactName=contactName.strip();email=email.strip().toLowerCase(Locale.ROOT);notes=notes.strip();if(contactName.isBlank()||contactName.length()>60||email.length()>160||!email.matches("[^@\\s]+@[^@\\s]+\\.[^@\\s]+")||notes.length()>500)throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Provide valid enquiry contact details.");}}
 public record Enquiry(UUID id,UUID owner,Quote quote,Contact contact,String status,Instant createdAt,String mode){public Enquiry{if(!owner.equals(quote.owner())||quote.travelPackage().fulfilment()!=Fulfilment.ENQUIRY||!"RECORDED_LOCALLY".equals(status)||!"MOCK".equals(mode))throw new IllegalArgumentException("Invalid enquiry state");}}
}
